using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor.SceneManagement;using Racer;using Object=UnityEngine.Object;
public static class CheckExistingRampRecovery {
 public static string Main(){var old=UnityEngine.SceneManagement.SceneManager.GetActiveScene().path;try{EditorSceneManager.OpenScene("Assets/Scenes/StreetLoopReverse.unity");Physics.SyncTransforms();var race=Object.FindAnyObjectByType<RaceDirector>();var car=race.vehicle;var reset=car.GetComponent<VehicleRespawn>();var flags=BindingFlags.NonPublic|BindingFlags.Instance;typeof(ArcadeVehicle).GetMethod("Awake",flags).Invoke(car,null);typeof(VehicleRespawn).GetMethod("Awake",flags).Invoke(reset,null);typeof(VehicleRespawn).GetField("race",flags).SetValue(reset,race);race.Racers.Clear();var state=new RacerState("ramp fixture",car,race.gates.Length-1,3);race.Racers.Add(state);var ramp=Object.FindObjectsByType<Collider>().First(c=>c.name=="Gully supported ramp");var bounds=ramp.bounds;int faces=0,rejected=0;var unsafeJump=typeof(VehicleRespawn).GetMethod("UnsafeJump",flags);
 for(float x=bounds.min.x+1;x<bounds.max.x;x+=2)for(float z=bounds.min.z+1;z<bounds.max.z;z+=2){if(!ramp.Raycast(new Ray(new(x,bounds.max.y+2,z),Vector3.down),out var hit,bounds.size.y+5)||hit.normal.y<.65f||hit.normal.y>.97f)continue;var branch=Object.FindObjectsByType<WoodlandRoute>().OrderBy(b=>{b.Project(hit.point,out float d);return d;}).First();branch.Project(hit.point,out float lateral);state.Branch.Clear();if(lateral<branch.halfWidth+1)state.Branch.Begin(branch);faces++;if((bool)unsafeJump.Invoke(reset,new object[]{hit.point+Vector3.up*.5f}))rejected++;}
 string result=(faces>0&&rejected==faces?"PASS ":"FAIL ")+$"Existing Gully ramp actual inclined surface: {rejected}/{faces} sampled faces excluded. Earlier AABB-centre probe was not a surface point; flat shared runout is intentionally usable.";File.WriteAllText("Docs/UndergroundPolish/existing-ramp-check.txt",result);return result;
 }finally{EditorSceneManager.OpenScene(old);}}
}
